template <typename T, int N> struct Ring {
    T items[N];
    int head = 0;
    void push(T value) { items[head++ % N] = value; }
    T total() const { T s{}; for (int i = 0; i < N; i++) s += items[i]; return s; }
};
struct Base { virtual int id() const { return 1; } virtual ~Base() = default; };
struct Left : virtual Base { int id() const override { return 2; } };
struct Right : virtual Base { int extra = 4; };
struct Both : Left, Right { int id() const override { return Left::id() + extra; } };
inline int shared_counter = 3;
static int calls() { static int count = 10; return ++count; }
struct Point { int x, y; Point operator+(const Point &o) const { return {x + o.x, y + o.y}; } };

int main() {
    Ring<int, 4> ring;
    for (int i = 1; i <= 6; i++) ring.push(i);
    int r = ring.total();
    Ring<double, 2> doubles;
    doubles.push(1.5); doubles.push(2.25);
    r += (int)(doubles.total() * 4);
    Base *object = new Both();
    r += object->id();
    delete object;
    int *array = new int[5];
    for (int i = 0; i < 5; i++) array[i] = i * i;
    r += array[4];
    delete[] array;
    auto twice = [r](int v) { return v * 2 + (r & 1); };
    r += twice(21);
    r += shared_counter + calls() + calls();
    Point a{1, 2}, b{3, 4};
    Point c = a + b;
    r += c.x * 10 + c.y;
    return r;
}
